  /* Psi4 */
  const double hnn_re = (hnn_0900*Power(X,9) + Power(X,3)*(hnn_0360*Power(Y,6) + Power(X,2)*(hnn_0720*Power(X,2)*Power(Y,2) + hnn_0540*Power(Y,4))))*R[0] + (hnn_2600*Power(X,6) + X*(hnn_2160*Power(Y,6) + X*(hnn_2240*Power(Y,4) + X*(hnn_2340*Power(Y,4) + X*(hnn_2420*Power(Y,2) + X*(hnn_2700*Power(X,2) + hnn_2520*Power(Y,2)))))))*R[2] + (hnn_4300*Power(X,3) + hnn_4040*Power(Y,4) + X*(hnn_4120*Power(Y,2) + hnn_4140*Power(Y,4) + X*(hnn_4220*Power(Y,2) + X*(X*(hnn_4400 + hnn_4500*X) + hnn_4320*Power(Y,2)))))*R[4] + (hnn_6000 + hnn_6100*X + hnn_6020*Power(Y,2) + X*(X*(hnn_6200 + hnn_6300*X) + hnn_6120*Power(Y,2)))*R[6] + (hnn_8000 + hnn_8100*X)*R[8];
